window.products.push({"id":1169442,"name":"Eddingtons Magnetic Retro Timer, Red","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81mqtVjo-yL._AC_SL1500_.jpg","description":"Time your kitchen tasks with style and accuracy. The Eddingtons retro timer will time anything up to 60 minutes. Simply twist the face of the timer all the way round to 60 minutes and then back to the desired time setting (this action winds the timer in a clockwork fashion to give a longer ring), when your time is up the timer will ring to notify you. Storage on any steel surface is easy with the strong built in magnet.","images":["https://m.media-amazon.com/images/I/81mqtVjo-yL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Eddingtons","source_asin":"B08Z3FY73K","category_path":"Home & Kitchen"},"sku":"BM-1169442","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08Z3FY73K","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08Z3FY73K","price_pending":true,"merchant_ready":false});
